def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([1]), fmt([5]), fmt([0, 0, 0]), fmt([3, 3, 3]), fmt([1, 1, 1, 1]), fmt([10**9] * 5), fmt([2, 1]), fmt([0, 1, 2, 3, 4, 5, 6, 7])]
    for n in (2, 3, 4, 6, 8, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([2, n, 2 * n])
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 100000) for _ in range(n)]))
    tests.append(fmt([n] * n))
    tests.append(fmt(sorted(rng.randint(0, 2 * n) for _ in range(n))))
    return tests
